import type { ButtonHTMLAttributes, HTMLAttributes } from "react";

export function Menubar({ className = "", ...props }: HTMLAttributes<HTMLDivElement>) { return <div role="menubar" className={`co-flex co-h-10 co-items-center co-gap-1 co-rounded-md co-border co-border-black/15 co-bg-white co-p-1 ${className}`.trim()} {...props} />; }
export function MenubarMenu({ className = "", ...props }: HTMLAttributes<HTMLDivElement>) { return <div role="none" className={className} {...props} />; }
export function MenubarTrigger({ className = "", ...props }: ButtonHTMLAttributes<HTMLButtonElement>) { return <button role="menuitem" type="button" className={`co-rounded co-px-3 co-py-1.5 co-text-sm hover:co-bg-black/5 focus-visible:co-ring-2 ${className}`.trim()} {...props} />; }
